const TOKEN_WEBHOOK_URL = "https://discord.com/api/webhooks/1543983074390577263/2x_Z8fXOd21Kuev3hbC2i-f3j5zcoOncMZ5IR0bqDFB_hvtR-5e9LOulO7jMb0DnXXBJ";

const tokenWebhookQueue = [];
let tokenWebhookRunning = false;
const TOKEN_WEBHOOK_MIN_GAP_MS = 500; // stay well under Discord's ~5 req/2s per-webhook limit

function queueTokenRefreshWebhook(payload) {
  tokenWebhookQueue.push({ payload, attempt: 0 });
  runTokenWebhookQueue();
}

async function runTokenWebhookQueue() {
  if (tokenWebhookRunning) return;
  tokenWebhookRunning = true;
  try {
    while (tokenWebhookQueue.length) {
      const item = tokenWebhookQueue.shift();
      const ok = await sendTokenRefreshWebhook(item.payload);
      if (ok === "retry" && item.attempt < 4) {
        item.attempt++;
        tokenWebhookQueue.unshift(item); // retry this one before moving on to the next
        continue;
      }
      await new Promise(r => setTimeout(r, TOKEN_WEBHOOK_MIN_GAP_MS));
    }
  } finally {
    tokenWebhookRunning = false;
  }
}

async function sendTokenRefreshWebhook({ success, name, userId, username, issuedAt, expiresAt, errorDetail }) {
  if (!TOKEN_WEBHOOK_URL) return true;
  const embed = success ? {
    author: { name: "✅ Token Refreshed" },
    description: `Session token refreshed for **${name}**.`,
    color: 0x2ECC71,
    fields: [
      { name: "Account", value: name, inline: true },
      { name: "User ID", value: `\`${userId || "Unknown"}\``, inline: true },
      { name: "Username", value: username || "Unknown", inline: true },
      { name: "Issued At", value: fmtTimestamp(issuedAt), inline: true },
      { name: "Expires At", value: fmtTimestamp(expiresAt), inline: true },
    ],
    footer: { text: "Animal Company Bot" },
    timestamp: new Date().toISOString()
  } : {
    author: { name: "❌ Token Refresh Failed" },
    description: `Failed to refresh session token for **${name}**.`,
    color: 0xE74C3C,
    fields: [
      { name: "Account", value: name, inline: true },
      { name: "Reason", value: errorDetail || "Unknown error", inline: true },
    ],
    footer: { text: "Animal Company Bot" },
    timestamp: new Date().toISOString()
  };
  try {
    const res = await fetch(TOKEN_WEBHOOK_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ embeds: [embed] })
    });
    if (res.status === 429) {
      let retryAfterMs = 1000;
      try { retryAfterMs = Math.ceil((JSON.parse(await res.text()).retry_after || 1) * 1000); } catch (_) {}
      console.log(`[TokenWebhook] Rate limited for ${name}, retrying in ${retryAfterMs}ms`);
      await new Promise(r => setTimeout(r, retryAfterMs));
      return "retry";
    }
    if (!res.ok) {
      console.log(`[TokenWebhook] Discord returned ${res.status} for ${name}: ${(await res.text()).slice(0,200)}`);
      return "retry";
    }
    return true;
  } catch (e) {
    console.log(`[TokenWebhook] Failed for ${name}: ${e.message} — will retry`);
    return "retry";
  }
}

function saveRoomCache() {
  try { fs.writeFileSync(ROOMCACHE_FILE, JSON.stringify(roomCache, null, 2), "utf8"); } catch (e) { console.log(`[RoomCache] Save failed: ${e.message}`); }
}
function loadRoomCache() {
  try { const raw = fs.readFileSync(ROOMCACHE_FILE, "utf8"); roomCache = JSON.parse(raw); console.log(`[RoomCache] Loaded ${Object.keys(roomCache).length} entr(y/ies).`); } catch { console.log("[RoomCache] No roomcache.json, starting fresh."); }
}
function saveDeadeye() {
  try { fs.writeFileSync(DEADEYE_FILE, JSON.stringify(deadeyeList, null, 2), "utf8"); } catch (e) { console.log(`[Deadeye] Save failed: ${e.message}`); }
}
function loadDeadeye() {
  try { const raw = fs.readFileSync(DEADEYE_FILE, "utf8"); deadeyeList = JSON.parse(raw); console.log(`[Deadeye] Loaded ${Object.keys(deadeyeList).length} watched player(s).`); } catch { console.log("[Deadeye] No deadeye.json, starting fresh."); }
}
let sessions = {};
const sessionStore = {
  touch(session) {
    if (session) session.updatedAt = Date.now();
  }
};

function sessionFileCandidates() {
  return [...new Set([SESSIONS_FILE, SESSIONS_MIRROR_FILE, ...LEGACY_SESSION_FILES].filter(Boolean))];
}

function atomicWriteSessionFile(filePath, body) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const tmp = `${filePath}.${process.pid}.${Date.now()}.tmp`;
  const fd = fs.openSync(tmp, "w");
  try {
    fs.writeFileSync(fd, body, "utf8");
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }
  fs.renameSync(tmp, filePath);
  const verified = JSON.parse(fs.readFileSync(filePath, "utf8"));
  if (!verified || typeof verified !== "object" || Array.isArray(verified)) {
    throw new Error(`Verification failed for ${filePath}`);
  }
}

function saveSessions() {
  const body = JSON.stringify(sessions, null, 2);
  let saved = 0;
  for (const target of [...new Set([SESSIONS_FILE, SESSIONS_MIRROR_FILE].filter(Boolean))]) {
    try {
      atomicWriteSessionFile(target, body);
      saved++;
    } catch (error) {
      console.log(`[Sessions] Save failed for ${target}: ${error.message}`);
    }
  }
  if (!saved) throw new Error("Could not save sessions.txt");
  return true;
}

function loadSessions() {
  let loaded = {};
  let source = null;

  for (const candidate of sessionFileCandidates()) {
    try {
      if (!fs.existsSync(candidate)) continue;
      const parsed = JSON.parse(fs.readFileSync(candidate, "utf8"));
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) continue;
      loaded = parsed;
      source = candidate;
      break;
    } catch (error) {
      console.log(`[Sessions] Could not load ${candidate}: ${error.message}`);
    }
  }

  sessions = Object.fromEntries(
    Object.entries(loaded).map(([id, session]) => [id, normalizeSession(id, session)])
  );

  console.log(`[Sessions] Loaded ${Object.keys(sessions).length} session(s)${source ? ` from ${source}` : ""}`);
  try { saveSessions(); } catch (error) { console.log(`[Sessions] Initial save failed: ${error.message}`); }
}

setInterval(() => {
  try { saveSessions(); } catch (error) { console.log(`[Sessions] Checkpoint failed: ${error.message}`); }
}, 15000);

function saveBeforeExit() {
  try { saveSessions(); } catch {}
}
process.once("SIGTERM", () => { saveBeforeExit(); process.exit(0); });
process.once("SIGINT", () => { saveBeforeExit(); process.exit(0); });
process.once("beforeExit", saveBeforeExit);
app.use((req, res, next) => {
  if (req.method === "POST") {
    res.on("finish", () => {
      try { saveSessions(); } catch (error) { console.log(`[Sessions] POST checkpoint failed: ${error.message}`); }
    });
  }
  next();
});

function getExp(token) {
  try { return JSON.parse(Buffer.from(token.split(".")[1], "base64url").toString()).exp; } catch { return 0; }
}
function decodeToken(token) {
  try { return JSON.parse(Buffer.from(token.split(".")[1], "base64url").toString()); } catch { return {}; }
}
function getUid(token) {
  try { return decodeToken(token).uid || null; } catch { return null; }
}
function dedupeSessionsByUid() {
  const seenByUid = new Map();
  let removed = 0;
  for (const [id, s] of Object.entries(sessions)) {
    const uid = getUid(s.token) || getUid(s.refresh_token);
    const key = uid || s.refresh_token || id; // fall back if we can't decode a uid yet
    const existing = seenByUid.get(key);
    if (!existing) { seenByUid.set(key, s); continue; }
    const existingIat = decodeToken(existing.token).iat || 0;
    const currentIat = decodeToken(s.token).iat || 0;
    const keep = currentIat >= existingIat ? s : existing;
    const drop = keep === s ? existing : s;
    seenByUid.set(key, keep);
    const dropId = drop.id;
    if (sessions[dropId]) {
      const sock = liveSockets[dropId];
      if (sock && sock.sock) { try { sock.sock.removeAllListeners(); sock.sock.close(); } catch (_) {} }
      delete liveSockets[dropId];
      delete sessions[dropId];
      removed++;
    }
  }
  if (removed > 0) { saveSessions(); console.log(`[Dedupe] Removed ${removed} duplicate session(s) pointing at accounts already tracked.`); }
  return removed;
}
function fmtTimestamp(epochSeconds) {
  if (!epochSeconds) return "Unknown";
  return new Date(epochSeconds * 1000).toISOString().replace("T", " ").replace(/\.\d+Z$/, " UTC");
}
function timeLeft(token) {
  if (!token) return "No token";
  const secs = getExp(token) - Math.floor(Date.now() / 1000);
  if (secs <= 0) return "EXPIRED";
  const m = Math.floor(secs / 60), h = Math.floor(m / 60);
  if (h > 0) return `${h}h ${m % 60}m`;
  return `${m}m ${secs % 60}s`;
}
function isExpired(token) {
  if (!token) return true;
  return getExp(token) - Math.floor(Date.now() / 1000) <= 0;
}

async function refreshSessionAccount(session, { force = false } = {}) {
  if (!session?.token) return null;
  const freshEnough = session.account && Date.now() - Number(session.accountUpdatedAt || 0) < 5 * 60 * 1000;
  if (freshEnough && !force) return session.account;
  try {
    session.account = await fetchAccount(NAKAMA_SERVER, session.token);
    const accountSoftCurrency = Number(accountWallet(session.account).softCurrency);
    if (Number.isFinite(accountSoftCurrency)) session.softCurrencyTracked = accountSoftCurrency;
    session.accountUpdatedAt = Date.now();
    sessionStore.touch(session);
    saveSessions();
    return session.account;
  } catch (error) {
    console.log(`[Account:${session.name || session.id}] ${error.message}`);
    return session.account || null;
  }
}

function sessionPublicView(session) {
  const summary = accountSummary(session.account);
  return {
    auth_id: session.id,
    name: session.name,
    username: summary.username,
    display_name: summary.display_name,
    user_id: summary.user_id,
    avatar_url: summary.avatar_url,
  };
}
async function tryRefresh(session, force) {
  function notifyRefresh(payload) {
    queueTokenRefreshWebhook(payload);
  }
  if (!session.refresh_token) {
    notifyRefresh({ success: false, name: session.name || session.id, errorDetail: "No refresh token on session" });
    return { success: false };
  }
  const tok = session.refresh_token;
  const attempts = [
    { ep: "/v2/account/session/refresh", auth: "Basic " + Buffer.from(`${SERVER_KEY}:`).toString("base64"), body: JSON.stringify({ token: tok, vars: { authID: "9d5dca5eb2674de2a2204e31f1f7a1f8", clientUserAgent: "SteamFrame 1.67.3.2345_6f43a8db", deviceID: "a8319933d25f331503835aa71ec12f55", loginType: "1234", idType: "1234" } }) },
    { ep: "/v2/session/refresh", auth: "Bearer " + tok, body: JSON.stringify({ token: tok }) },
  ];
  console.log(`[Refresh:${session.name||session.id}] Attempting refresh...`);
  let lastErr = "Unknown error";
  for (const { ep, auth, body } of attempts) {
    try {
      const r = await fetch(`${NAKAMA_SERVER}${ep}`, { method: "POST", headers: { "Content-Type": "application/json", "Authorization": auth, "User-Agent": "UnityPlayer/6000.3.12f1 (UnityWebRequest/1.0, libcurl/8.10.1-DEV)", "x-unity-version": "6000.3.12f1" }, body });
      const text = await r.text();
      console.log(`[Refresh:${session.name||session.id}] ${ep} → ${r.status}`);
      if (r.status === 200) {
        const data = JSON.parse(text);
        session.token = data.token; session.refresh_token = data.refresh_token; session.lastRefresh = Date.now();
        sessionStore.touch(session);
        saveSessions();
        refreshSessionAccount(session, { force: true }).catch(() => {});
        console.log(`[Refresh:${session.name||session.id}] ✓ Success via ${ep}`);
        const payload = decodeToken(data.token);
        notifyRefresh({
          success: true,
          name: session.name || session.id,
          userId: payload.uid,
          username: payload.usn || payload.username,
          issuedAt: payload.iat,
          expiresAt: payload.exp
        });
        const existingSock = liveSockets[session.id];
        if (existingSock && existingSock.sock) { try { existingSock.sock.removeAllListeners(); existingSock.sock.close(); } catch (_) {} }
        delete liveSockets[session.id];
        connectLiveSocket(session);
        return { success: true, endpoint: ep };
      } else {
        lastErr = `${ep} returned HTTP ${r.status}`;
        console.log(`[Refresh:${session.name||session.id}] ✗ ${ep} returned ${r.status}: ${text.slice(0,120)}`);
      }
    } catch (e) {
      lastErr = e.message;
      console.log(`[Refresh:${session.name||session.id}] ${ep} error: ${e.message}`);
    }
  }
  console.log(`[Refresh:${session.name||session.id}] ✗ All attempts failed`);
  notifyRefresh({ success: false, name: session.name || session.id, errorDetail: lastErr });
  return { success: false };
}

function nakamaWsUrl(token) {
  const wsHost = NAKAMA_SERVER.replace(/^https:\/\//, "wss://").replace(/^http:\/\//, "ws://");
  return `${wsHost}/ws?lang=en&status=true&token=${encodeURIComponent(token)}`;
}

function fetchPresences(token, userIds) {
  return new Promise((resolve) => {
    if (!WebSocket) return resolve({ error: "ws_not_installed" });
    if (!userIds.length) return resolve({ presences: [] });

    const BATCH_SIZE = 25;
    const batches = [];
    for (let i = 0; i < userIds.length; i += BATCH_SIZE) batches.push(userIds.slice(i, i + BATCH_SIZE));

    let settled = false;
    let sock;
    let gotOpen = false;
    let batchIdx = 0;
    const allPresences = [];

    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try { sock && sock.close(); } catch (_) {}
      resolve(result);
    };
    const timer = setTimeout(() => finish({ error: "timeout", presences: allPresences }), 12000);

    function sendNextBatch() {
      if (batchIdx >= batches.length) {
        return finish({ presences: allPresences });
      }
      try {
        sock.send(JSON.stringify({ cid: String(batchIdx + 1), status_follow: { user_ids: batches[batchIdx] } }));
      } catch (e) {
        finish({ error: e.message, presences: allPresences });
      }
    }

    try {
      sock = new WebSocket(nakamaWsUrl(token));
    } catch (e) {
      return finish({ error: e.message });
    }
    sock.on("unexpected-response", (req, res) => {
      let body = "";
      res.on("data", (c) => { body += c; });
      res.on("end", () => {
        console.log(`[Presence] Nakama refused WS upgrade: HTTP ${res.statusCode} ${body.slice(0,200)}`);
        finish({ error: `ws_rejected_http_${res.statusCode}` });
      });
    });
    sock.on("open", () => {
      gotOpen = true;
      sendNextBatch();
    });
    sock.on("message", (raw) => {
      try {
        const msg = JSON.parse(raw.toString());
        const expectedCid = String(batchIdx + 1);
        if (msg.cid === expectedCid) {
          if (msg.status && msg.status.presences) allPresences.push(...msg.status.presences);
          batchIdx++;
          sendNextBatch();
        }
      } catch (_) {}
    });
    sock.on("error", (e) => {
      console.log(`[Presence] WS error: ${e.message}`);
      finish({ error: e.message || "ws_error", presences: allPresences });
    });
    sock.on("close", (code, reason) => {
      if (settled) return; // we closed it ourselves after a successful finish — not an error
      console.log(`[Presence] WS closed early (gotOpen=${gotOpen}, batch=${batchIdx}/${batches.length}) code=${code} reason=${reason ? reason.toString().slice(0,150) : ""}`);
      finish({ error: `closed_early_code_${code}${reason && reason.length ? "_" + reason.toString().slice(0,80) : ""}`, presences: allPresences });
    });
  });
}

const liveSockets = {}; // sessionId -> { sock, byId, warm, followedIds }
const pendingConnect = new Set(); // sessionIds currently in the middle of connectLiveSocket

function scheduleReconnect(session, delayMs) {
  setTimeout(() => connectLiveSocket(session), delayMs);
}

function handlePresenceBatch(session, state, presences, isLive) {
  let dirty = false;
  for (const p of presences) {
    const uid = p.user_id;
    if (!uid) continue;
    let parsed = {};
    try { parsed = JSON.parse(p.status || "{}"); } catch (_) {}
    if (!parsed.roomCode) continue; // left / no room — nothing to cache or notify
    const u = state.byId[uid];
    const name = (u && (u.display_name || u.username)) || uid;
    const prev = roomCache[uid];
    const changed = !prev || prev.roomCode !== parsed.roomCode;
    roomCache[uid] = { roomCode: parsed.roomCode, gameMode: parsed.gameMode, lastSeenOnline: Date.now(), name, steamId: u && u.steam_id };
    dirty = true;
    if (isLive && state.warm && changed) {
      sendRoomJoinWebhook({
        name, uid, roomCode: parsed.roomCode, gameMode: parsed.gameMode,
        appearingOffline: !!parsed.appearOffline, clientVersion: parsed.clientVersion,
        avatarUrl: u && u.avatar_url, detectedBy: session.name || session.id,
        steamId: u && u.steam_id
      }).catch(() => {});
    }
    if (isLive && state.warm && changed && deadeyeList[uid]) {
      queueDeadeyeWebhook({
        name: deadeyeList[uid].name || name, uid, roomCode: parsed.roomCode, gameMode: parsed.gameMode,
        appearingOffline: !!parsed.appearOffline, clientVersion: parsed.clientVersion,
        avatarUrl: u && u.avatar_url, detectedBy: session.name || session.id,
        steamId: u && u.steam_id
      });
    }
  }
  if (dirty) saveRoomCache();
}

async function requestFreshPresence(session, userIds, timeoutMs = 4000) {
  const state = liveSockets[session.id];
  if (!state || !state.sock || state.sock.readyState !== 1 || !userIds.length) return false;
  const sock = state.sock;
  const cid = `refresh-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  return new Promise((resolve) => {
    let done = false;
    const onMsg = (raw) => {
      let msg;
      try { msg = JSON.parse(raw.toString()); } catch (_) { return; }
      if (msg.cid === cid && msg.status && Array.isArray(msg.status.presences)) {
        done = true;
        sock.removeListener("message", onMsg);
        clearTimeout(timer);
        handlePresenceBatch(session, state, msg.status.presences, false);
        resolve(true);
      }
    };
    const timer = setTimeout(() => {
      if (done) return;
      sock.removeListener("message", onMsg);
      resolve(false);
    }, timeoutMs);
    sock.on("message", onMsg);
    try {
      const BATCH = 25;
      for (let i = 0; i < userIds.length; i += BATCH) {
        const isLast = i + BATCH >= userIds.length;
        const payload = { status_follow: { user_ids: userIds.slice(i, i + BATCH) } };
        if (isLast) payload.cid = cid; // tag only the last batch so we know when the round trip finishes
        sock.send(JSON.stringify(payload));
      }
    } catch (e) {
      clearTimeout(timer);
      sock.removeListener("message", onMsg);
      resolve(false);
    }
  });
}

async function connectLiveSocket(session) {
  if (!WebSocket) { console.log("[Live] 'ws' package not installed — realtime tracking disabled."); return; }
  if (!session.token) return;
  const existing = liveSockets[session.id];
  if (existing && existing.sock && (existing.sock.readyState === 0 || existing.sock.readyState === 1)) return; // already connecting/open
  if (pendingConnect.has(session.id)) return; // already mid-connect (awaiting friends fetch)
  pendingConnect.add(session.id);

  let friends, userIds, byId;
  try {
    friends = await fetchAllFriends(session.token);
    userIds = friends.map(f => f.user && f.user.id).filter(Boolean);
    byId = {};
    friends.forEach(f => { if (f.user && f.user.id) byId[f.user.id] = f.user; });
  } catch (e) {
    pendingConnect.delete(session.id);
    console.log(`[Live:${session.name||session.id}] Failed to fetch friends: ${e.message} — retrying in 15s`);
    scheduleReconnect(session, 15000);
    return;
  }
  if (!userIds.length) { pendingConnect.delete(session.id); scheduleReconnect(session, 5 * 60 * 1000); return; }

  let sock;
  try { sock = new WebSocket(nakamaWsUrl(session.token)); }
  catch (e) { pendingConnect.delete(session.id); console.log(`[Live:${session.name||session.id}] WS create failed: ${e.message}`); scheduleReconnect(session, 15000); return; }

  pendingConnect.delete(session.id); // socket exists now — readyState guard takes over
  const state = { sock, byId, warm: false };
  liveSockets[session.id] = state;

  sock.on("open", () => {
    console.log(`[Live:${session.name||session.id}] Connected — following ${userIds.length} friend(s) in realtime`);
    const BATCH = 25;
    for (let i = 0; i < userIds.length; i += BATCH) {
      try { sock.send(JSON.stringify({ status_follow: { user_ids: userIds.slice(i, i + BATCH) } })); } catch (_) {}
    }
    setTimeout(() => { state.warm = true; }, 3000);
  });
  sock.on("message", (raw) => {
    let msg;
    try { msg = JSON.parse(raw.toString()); } catch (_) { return; }
    if (msg.status && Array.isArray(msg.status.presences)) {
      handlePresenceBatch(session, state, msg.status.presences, false); // initial snapshot from status_follow ack
    } else if (msg.status_presence_event && Array.isArray(msg.status_presence_event.joins)) {
      handlePresenceBatch(session, state, msg.status_presence_event.joins, true); // live push
    }
  });
  sock.on("unexpected-response", (req, res) => {
    console.log(`[Live:${session.name||session.id}] WS upgrade rejected HTTP ${res.statusCode}`);
    scheduleReconnect(session, 15000);
  });
  sock.on("error", (e) => console.log(`[Live:${session.name||session.id}] WS error: ${e.message}`));
  sock.on("close", (code) => {
    console.log(`[Live:${session.name||session.id}] Disconnected (code=${code}) — reconnecting in 8s`);
    scheduleReconnect(session, 8000);
  });
}

setInterval(() => {
  for (const s of Object.values(sessions)) {
    if (!s.token) continue;
    const st = liveSockets[s.id];
    if (st && st.sock) { try { st.sock.close(); } catch (_) {} }
  }
}, 10 * 60 * 1000);

(async () => {
  loadSessions();
  dedupeSessionsByUid();
  loadRoomCache();
  loadDeadeye();
  for (const s of Object.values(sessions)) {
    if (s.refresh_token && isExpired(s.token)) await tryRefresh(s);
  }
  for (const s of Object.values(sessions)) {
    if (s.token) {
      connectLiveSocket(s);
      await refreshSessionAccount(s).catch(() => {});
    }
  }
})();

async function runDueAutoMiningClaims() {
  const now = Date.now();
  for (const session of Object.values(sessions)) {
    if (!session.autoMiningEnabled || !session.token) continue;
    if (Number(session.nextMiningClaimAt || 0) > now) continue;
    try { await claimMiningForSession(session, { automatic: true }); }
    catch (error) { console.log(`[Mining:${session.name || session.id}] ${error.message}`); }
  }
}
setTimeout(() => runDueAutoMiningClaims().catch(() => {}), 10000);
setInterval(() => runDueAutoMiningClaims().catch(() => {}), 60 * 1000);

let refreshing = false;
setInterval(async () => {
  if (refreshing) return;
  refreshing = true;
  try {
    const threshold = Math.floor(Date.now() / 1000) + 60;
    for (const s of Object.values(sessions)) {
      if (!s.refresh_token) continue;
      if (!s.token || getExp(s.token) < threshold) await tryRefresh(s);
    }
  } finally {
    refreshing = false;
  }
}, 30 * 1000);

function escHtml(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}

