app.post("/session/:id/claim-mining", async (req, res) => {
  const s = sessions[req.params.id];
  if (!s) return res.status(404).json({ error: "Not found" });
  try {
    const result = await claimMiningForSession(s);
    const summary = miningResultSummary(result);
    const message = summary.succeeded === false ? `Mining claim returned ${summary.errorCode || "an error"}` : "Mining rewards claimed";
    res.redirect(sessionPageUrl(s.id, message, summary.succeeded === false));
  } catch (error) {
    res.redirect(sessionPageUrl(s.id, error.message, true));
  }
});

app.post("/session/:id/auto-mining", async (req, res) => {
  const s = sessions[req.params.id];
  if (!s) return res.status(404).json({ error: "Not found" });
  const enabled = String(req.body.enabled).toLowerCase() === "true";
  s.autoMiningEnabled = enabled;
  s.nextMiningClaimAt = enabled ? Date.now() : 0;
  sessionStore.touch(s);
  saveSessions();
  if (enabled && s.token) {
    try { await claimMiningForSession(s, { automatic: true }); }
    catch (error) { return res.redirect(sessionPageUrl(s.id, `Auto mining enabled, but the first claim failed: ${error.message}`, true)); }
  }
  res.redirect(sessionPageUrl(s.id, enabled ? "Auto mining enabled. Claims run every 12 hours." : "Auto mining disabled."));
});

app.post("/session/:id/delete",(req,res)=>{
  const ex=liveSockets[req.params.id];
  if(ex&&ex.sock){try{ex.sock.removeAllListeners();ex.sock.close();}catch(_){}}
  delete liveSockets[req.params.id];
  delete sessions[req.params.id];saveSessions();res.redirect("/");
});
app.post("/refresh-all",async(req,res)=>{
  for(const s of Object.values(sessions))await tryRefresh(s, true);
  if(req.headers["accept"]?.includes("application/json")) return res.json({ok:true});
  res.redirect("/");
});
app.post("/clean-duplicates",(req,res)=>{
  const seen=new Map();
  for(const[id,s]of Object.entries(sessions)){
    const key=s.refresh_token||id;
    if(seen.has(key)){delete sessions[id];}
    else seen.set(key,id);
  }
  saveSessions();res.redirect("/");
});

async function getLivePresenceForUids(uids) {
  const validSessions = Object.values(sessions).filter(s=>!isExpired(s.token));
  if (!validSessions.length || !uids.length) return { presenceMap: {}, anySucceeded: false, error: "no_valid_session" };

  const results = await Promise.all(validSessions.map(s => fetchPresences(s.token, uids)));
  const presenceMap = {};
  let anySucceeded = false;
  let lastError = null;
  for (const presenceResult of results) {
    if (presenceResult.error) lastError = presenceResult.error;
    if (!presenceResult.presences) continue;
    anySucceeded = true;
    for (const p of presenceResult.presences) {
      let parsed = {};
      try { parsed = JSON.parse(p.status || "{}"); } catch (_) {}
      const existing = presenceMap[p.user_id];
      if (existing && !parsed.roomCode && existing.roomCode) continue;
      presenceMap[p.user_id] = { roomCode: parsed.roomCode || null, gameMode: parsed.gameMode, appearOffline: !!parsed.appearOffline, clientVersion: parsed.clientVersion || null };
    }
  }
  return { presenceMap, anySucceeded, error: lastError };
}

app.get("/deadeye",async(req,res)=>{
  const entries = Object.values(deadeyeList);
  if (!entries.length) return res.json(entries);

  const uids = entries.map(e => e.uid);
  const { presenceMap, anySucceeded, error } = await getLivePresenceForUids(uids);
  if (!Object.values(sessions).some(s=>!isExpired(s.token))) {
    return res.json(entries.map(e => ({ ...e, online: null, appearingOffline: false, roomCode: roomCache[e.uid]?.roomCode || null, steamId: e.steamId || roomCache[e.uid]?.steamId || null, presenceError: "no_valid_session" })));
  }

  const enriched = entries.map(e => {
    const pres = presenceMap[e.uid];
    const cached = roomCache[e.uid];
    return {
      ...e,
      online: !!pres,
      appearingOffline: !!(pres && pres.appearOffline),
      roomCode: (pres && pres.roomCode) || (cached ? cached.roomCode : null),
      steamId: e.steamId || (cached ? cached.steamId : null),
      presenceError: anySucceeded ? null : error
    };
  });
  res.json(enriched);

});
async function fetchUserInfoByIds(token, uids) {
  try {
    const qs = uids.map(id => `ids=${encodeURIComponent(id)}`).join("&");
    const r = await fetch(`${NAKAMA_SERVER}/v2/user?${qs}`, {
      headers: {
        "Authorization": `Bearer ${token}`,
        "User-Agent": "UnityPlayer/6000.3.12f1 (UnityWebRequest/1.0, libcurl/8.10.1-DEV)",
        "x-unity-version": "6000.3.12f1"
      }
    });
    if (!r.ok) return null;
    const data = await r.json();
    return (data && data.users) || [];
  } catch (e) {
    return null;
  }
}

app.post("/deadeye/add",async(req,res)=>{
  const { uid, name } = req.body || {};
  if (!uid) return res.status(400).json({ error: "uid is required" });
  deadeyeList[uid] = { uid, name: name || uid, addedAt: Date.now() };
  saveDeadeye();
  res.json({ ok: true, entry: deadeyeList[uid] }); // respond immediately, don't block on the presence check

  const anySession = Object.values(sessions).find(s => !isExpired(s.token));
  let steamId = roomCache[uid] && roomCache[uid].steamId;
  if (anySession) {
    const users = await fetchUserInfoByIds(anySession.token, [uid]);
    const u = users && users[0];
    if (u && u.steam_id) steamId = u.steam_id;
  }
  if (steamId && deadeyeList[uid]) {
    deadeyeList[uid].steamId = steamId;
    saveDeadeye();
  }

  const { presenceMap } = await getLivePresenceForUids([uid]);
  const pres = presenceMap[uid];
  const cached = roomCache[uid];
  const roomCode = (pres && pres.roomCode) || (cached ? cached.roomCode : null);
  if (roomCode) {
    queueDeadeyeWebhook({
      name: name || (cached && cached.name) || uid, uid, roomCode,
      gameMode: (pres && pres.gameMode) || (cached ? cached.gameMode : null),
      appearingOffline: !!(pres && pres.appearOffline),
      clientVersion: pres && pres.clientVersion,
      avatarUrl: undefined, detectedBy: "Amblock",
      steamId
    });
  }

});
app.post("/deadeye/remove",(req,res)=>{
  const { uid } = req.body || {};
  if (!uid || !deadeyeList[uid]) return res.status(404).json({ error: "not found" });
  delete deadeyeList[uid];
  saveDeadeye();
  res.json({ ok: true });
});

app.post("/deadeye/friend-request",async(req,res)=>{
  const { uid, sessionId } = req.body || {};
  if (!uid) return res.status(400).json({ error: "uid is required" });
  const s = sessionId ? sessions[sessionId] : Object.values(sessions).find(s=>!isExpired(s.token));
  if (!s || isExpired(s.token)) return res.status(400).json({ error: "no valid session available to send the request from" });
  try {
    const r = await fetch(`${NAKAMA_SERVER}/v2/friend?ids=${encodeURIComponent(uid)}`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${s.token}`,
        "User-Agent": "UnityPlayer/6000.3.12f1 (UnityWebRequest/1.0, libcurl/8.10.1-DEV)",
        "x-unity-version": "6000.3.12f1"
      }
    });
    if (!r.ok) {
      const text = await r.text();
      return res.status(r.status).json({ error: `Nakama returned ${r.status}: ${text.slice(0,200)}` });
    }
    res.json({ ok: true, sentFrom: s.name || s.id });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

